insertion_sort_list(Head) -> sort_nodes(Head, null). sort_nodes(null, Sorted) -> Sorted; sort_nodes(#list_node{val = V, next = Next}, Sorted) -> sort_nodes(Next, insert(V, Sorted)). insert(V, null) -> #list_node{val = V, next = null}; insert(V, Node = #list_node{val = W}) when V < W -> #list_node{val = V, next = Node}; insert(V, Node = #list_node{next = Next}) -> Node#list_node{next = insert(V, Next)}.
